using System.Reflection;
using System.Reflection.Emit;

public static Func<T, object> CreateGetter<T>(string propertyName)
{
    PropertyInfo prop = typeof(T).GetProperty(propertyName);
    DynamicMethod getter = new DynamicMethod(
        "get_", typeof(object), new[] { typeof(T) }, typeof(T));

    ILGenerator il = getter.GetILGenerator();
    il.Emit(OpCodes.Ldarg_0);       // load the instance
    il.Emit(OpCodes.Callvirt, prop.GetGetMethod());

n    // Box value types to object
    if (prop.PropertyType.IsValueType)
        il.Emit(OpCodes.Box, prop.PropertyType);

    il.Emit(OpCodes.Ret);

    return (Func<T, object>)getter.CreateDelegate(typeof(Func<T, object>));
}

// Usage — compiled delegate is as fast as hand-written code
